-- setup.sql — sample database for: prBookSeat: the atomic UPDATE + @@ROWCOUNT as a procedure
-- Drops and re-creates the database DBI202_CL (a scratch database used only by Code Lab exercises), then the tables + rows.
-- Xoá và tạo lại CSDL DBI202_CL (CSDL nháp chỉ dùng cho bài Code Lab), rồi tạo bảng + dữ liệu. Chạy lại bất cứ lúc nào để làm sạch.
USE master;
GO
IF DB_ID(N'DBI202_CL') IS NOT NULL
BEGIN
    ALTER DATABASE DBI202_CL SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE DBI202_CL;
END
GO
CREATE DATABASE DBI202_CL;
GO
USE DBI202_CL;
GO
CREATE TABLE Course (cid CHAR(6) NOT NULL PRIMARY KEY, title NVARCHAR(60) NOT NULL, seats INT NOT NULL);
INSERT INTO Course VALUES ('DBI202', N'Database Systems', 1), ('CSD201', N'Data Structures', 0), ('PRF192', N'Programming', 30);
GO
PRINT N'setup.sql: database DBI202_CL ready.';

-- check.sql — self-check for: prBookSeat: the atomic UPDATE + @@ROWCOUNT as a procedure
-- Generated with the exercise — DO NOT EDIT. Run it AFTER setup.sql and your solution.sql (see the task text).
-- Tự kiểm cho bài này — sinh kèm đề, ĐỪNG SỬA. Chạy SAU setup.sql và solution.sql của bạn (xem đề).
USE DBI202_CL;
GO
SET NOCOUNT ON;
DECLARE @ok BIT, @info NVARCHAR(4000), @pass INT = 0, @fail INT = 0;
PRINT N'────────── check.sql: 3 checks ──────────';

-- CHECK 1: The first booking of DBI202 succeeds, the second fails
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @a BIT, @b BIT; BEGIN TRAN; EXEC dbo.prBookSeat ''DBI202'', @a OUTPUT; EXEC dbo.prBookSeat ''DBI202'', @b OUTPUT;
SET @ok = IIF(@a = 1 AND @b = 0 AND (SELECT seats FROM Course WHERE cid = ''DBI202'') = 0, 1, 0); SET @info = CONCAT(N''first='', @a, N'' second='', @b, N'' seats='', (SELECT seats FROM Course WHERE cid = ''DBI202'')); ROLLBACK;',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 1. The first booking of DBI202 succeeds, the second fails | Lần đặt đầu của DBI202 thành công, lần hai thất bại'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 1. The first booking of DBI202 succeeds, the second fails | Lần đặt đầu của DBI202 thành công, lần hai thất bại', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 2: A full course: @booked = 0, seats stay 0
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @a BIT; BEGIN TRAN; EXEC dbo.prBookSeat ''CSD201'', @a OUTPUT;
SET @ok = IIF(@a = 0 AND (SELECT seats FROM Course WHERE cid = ''CSD201'') = 0, 1, 0); SET @info = CONCAT(N''booked='', @a); ROLLBACK;',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 2. A full course: @booked = 0, seats stay 0 | Môn đầy: @booked = 0, chỗ vẫn 0'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 2. A full course: @booked = 0, seats stay 0 | Môn đầy: @booked = 0, chỗ vẫn 0', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 3: An unknown course: @booked = 0
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @a BIT; EXEC dbo.prBookSeat ''XXX999'', @a OUTPUT; SET @ok = IIF(@a = 0, 1, 0); SET @info = CONCAT(N''booked='', @a);',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 3. An unknown course: @booked = 0 | Môn không tồn tại: @booked = 0'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 3. An unknown course: @booked = 0 | Môn không tồn tại: @booked = 0', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

PRINT N'──────────────────────────────────────';
IF @fail = 0 PRINT CONCAT(N'ALL ', @pass, N' CHECKS PASSED — go back to Code Lab and press "Mark as solved".');
ELSE PRINT CONCAT(@pass, N' passed, ', @fail, N' FAILED — fix solution.sql, then run setup.sql, solution.sql, check.sql again.');
SELECT CASE WHEN @fail = 0 THEN N'ALL CHECKS PASSED' ELSE N'NOT YET' END AS Result, @pass AS Passed, @fail AS Failed;
IF @fail > 0 RAISERROR(N'%d check(s) failed', 16, 1, @fail);

